class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Initialize adjacency list representation of the graph
        adj_list = [[] for _ in range(n)]
        for u, v, w in edges:
            adj_list[u].append((v, w))
            adj_list[v].append((u, w))

        # Helper function to perform DFS and update distances
        def dfs(node, parent, distance):
            for neighbor, weight in adj_list[node]:
                if neighbor != parent:
                    new_distance = distance + weight
                    if new_distance > threshold:
                        continue
                    if new_distance not in visited or new_distance < visited[neighbor]:
                        visited[neighbor] = new_distance
                        dfs(neighbor, node, new_distance)

        # Find all connected components
        visited = {}
        component = 0
        for i in range(n):
            if i not in visited:
                component += 1
                visited[i] = 0
                dfs(i, None, 0)

        # Check if we can form a valid graph
        for i in range(n):
            for j in range(i+1, n):
                if visited[i] > threshold and visited[j] > threshold:
                    return -1

        # Calculate the minimum maximum weight using Kruskal's algorithm
        edges.sort(key=lambda x: x[2])
        uf = UnionFind(n)
        max_weight = 0
        for u, v, w in edges:
            if uf.union(u, v):
                max_weight = max(max_weight, w)

        return max_weight

# Helper class for union-find data structure
class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            self.parent[root_x] = root_y
            return True
        return False

