class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Create adjacency list representation of the graph
        adj_list = [[] for _ in range(n)]
        for u, v, w in edges:
            adj_list[u].append((v, w))
            adj_list[v].append((u, w))

        # Find connected components using DFS
        visited = set()
        def dfs(node):
            if node in visited:
                return
            visited.add(node)
            for neighbor, weight in adj_list[node]:
                dfs(neighbor)

        components = []
        for i in range(n):
            if i not in visited:
                component = []
                dfs(i)
                components.append(component)

        # Initialize result variable
        res = float('inf')

        # Iterate over each component
        for component in components:
            if len(component) < threshold:
                continue

            # Perform union-find to find the smallest edge weight in the component
            parent = {}
            rank = {}

            def find(x):
                if x not in parent:
                    parent[x] = x
                    rank[x] = 0
                elif parent[x] != x:
                    parent[x] = find(parent[x])
                return parent[x]

            def union(x, y):
                root_x = find(x)
                root_y = find(y)

                if root_x == root_y:
                    return

                if rank[root_x] > rank[root_y]:
                    parent[root_y] = root_x
                else:
                    parent[root_x] = root_y
                    if rank[root_x] == rank[root_y]:
                        rank[root_y] += 1

            # Calculate the minimum edge weight in the component
            min_weight = float('inf')
            for i in range(len(component)):
                for j in range(i + 1, len(component)):
                    min_weight = min(min_weight, adj_list[component[i]][component[j]][1])

            # Update result
            res = min(res, min_weight)

        # Return result or -1 if no valid component found
        return res if res != float('inf') else -1

